86	fn build_application() -> Application {
87	    let platform = gpui_platform::current_platform(false);
88	    if std::env::var("ZED_EXPERIMENTAL_A11Y").as_deref() == Ok("1") {
89	        Application::with_platform(platform)
90	    } else {
91	        Application::new_inaccessible(platform)
92	    }
93	}
94	
95	fn files_not_created_on_launch(errors: HashMap<io::ErrorKind, Vec<&Path>>) {
96	    let message = "Zed failed to launch";
97	    let error_details = errors
98	        .into_iter()
99	        .flat_map(|(kind, paths)| {
100	            #[allow(unused_mut)] // for non-unix platforms
101	            let mut error_kind_details = match paths.len() {
102	                0 => return None,
103	                1 => format!(
104	                    "{kind} when creating directory {:?}",
105	                    paths.first().expect("match arm checks for a single entry")
106	                ),
107	                _many => format!("{kind} when creating directories {paths:?}"),
108	            };
109	
110	            #[cfg(unix)]
111	            {
112	                if kind == io::ErrorKind::PermissionDenied {
113	                    error_kind_details.push_str("\n\nConsider using chown and chmod tools for altering the directories permissions if your user has corresponding rights.\
114	                        \nFor example, `sudo chown $(whoami):staff ~/.config` and `chmod +uwrx ~/.config`");
115	                }
116	            }
117	
118	            Some(error_kind_details)
119	        })
120	        .collect::<Vec<_>>().join("\n\n");
121	
122	    eprintln!("{message}: {error_details}");
123	    build_application()
124	        .with_quit_mode(QuitMode::Explicit)
125	        .run(move |cx| {
126	            if let Ok(window) = cx.open_window(gpui::WindowOptions::default(), |_, cx| {
127	                cx.new(|_| gpui::Empty)
128	            }) {
129	                window
130	                    .update(cx, |_, window, cx| {
131	                        let response = window.prompt(
132	                            gpui::PromptLevel::Critical,
133	                            message,
134	                            Some(&error_details),
135	                            &["Exit"],
136	                            cx,
137	                        );
138	
139	                        cx.spawn_in(window, async move |_, cx| {
140	                            response.await?;
141	                            cx.update(|_, cx| cx.quit())
142	                        })
143	                        .detach_and_log_err(cx);
144	                    })
145	                    .log_err();
146	            } else {
147	                fail_to_open_window(anyhow::anyhow!("{message}: {error_details}"), cx)
148	            }
149	        })
150	}
151	
152	fn fail_to_open_window_async(e: anyhow::Error, cx: &mut AsyncApp) {
153	    cx.update(|cx| fail_to_open_window(e, cx));
154	}
155	
156	fn fail_to_open_window(e: anyhow::Error, _cx: &mut App) {
157	    eprintln!(
158	        "Zed failed to open a window: {e:?}. See https://zed.dev/docs/linux for troubleshooting steps."
159	    );
160	    #[cfg(not(any(target_os = "linux", target_os = "freebsd")))]
161	    {
162	        process::exit(1);
163	    }
164	
165	    // Maybe unify this with gpui::platform::linux::platform::ResultExt::notify_err(..)?
166	    #[cfg(any(target_os = "linux", target_os = "freebsd"))]
167	    {
168	        use ashpd::desktop::notification::{Notification, NotificationProxy, Priority};
169	        _cx.spawn(async move |_cx| {
170	            let Ok(proxy) = NotificationProxy::new().await else {
171	                process::exit(1);
172	            };
173	
174	            let notification_id = "dev.zed.Oops";
175	            proxy
176	                .add_notification(
177	                    notification_id,
178	                    Notification::new("Zed failed to launch")
179	                        .body(Some(
180	                            format!(
181	                                "{e:?}. See https://zed.dev/docs/linux for troubleshooting steps."
182	                            )
183	                            .as_str(),
184	                        ))
185	                        .priority(Priority::High)
186	                        .icon(ashpd::desktop::Icon::with_names(&[
187	                            "dialog-question-symbolic",
188	                        ])),
189	                )
190	                .await
191	                .ok();
192	
193	            process::exit(1);
194	        })
195	        .detach();
196	    }
197	}
198	static STARTUP_TIME: OnceLock<Instant> = OnceLock::new();
199	
200	fn main() {
201	    STARTUP_TIME.get_or_init(|| Instant::now());
202	
203	    // If this process was re-executed as a Linux sandbox helper, run that mode
204	    // without returning. Must run before argument parsing: the wrapped command's
205	    // args are appended verbatim and would otherwise be misinterpreted as Zed's
206	    // own arguments.
207	    sandbox::run_sandbox_launcher_if_invoked();
208	
209	    #[cfg(unix)]
210	    util::prevent_root_execution();
211	
212	    let args = Args::parse();
213	
214	    // `zed --askpass` Makes zed operate in nc/netcat mode for use with askpass
215	    #[cfg(not(target_os = "windows"))]
216	    if let Some(socket) = &args.askpass {
217	        askpass::main(socket);
218	        return;
219	    }
220	
221	    // `zed --crash-handler` Makes zed operate in minidump crash handler mode
222	    if let Some(socket) = &args.crash_handler {
223	        crashes::crash_server(socket.as_path(), paths::logs_dir().clone());
224	        return;
225	    }
226	
227	    #[cfg(target_os = "windows")]
228	    if args.record_etw_trace {
229	        let zed_pid = args
230	            .etw_zed_pid
231	            .and_then(|pid| if pid >= 0 { Some(pid as u32) } else { None });
232	        let Some(output_path) = args.etw_output else {
233	            eprintln!("--etw-output is required for --record-etw-trace");
234	            process::exit(1);
235	        };
236	
237	        let Some(etw_socket) = args.etw_socket else {
238	            eprintln!("--etw-socket is required for --record-etw-trace");
239	            process::exit(1);
240	        };
241	
242	        if let Err(error) =
243	            etw_tracing::record_etw_trace(zed_pid, &output_path, etw_socket.as_str())
244	        {
245	            eprintln!("ETW trace recording failed: {error:#}");
246	            process::exit(1);
247	        }
248	        return;
249	    }
250	
251	    #[cfg(all(not(debug_assertions), target_os = "windows"))]
252	    unsafe {
253	        use windows::Win32::System::Console::{ATTACH_PARENT_PROCESS, AttachConsole};
254	
255	        if args.foreground {
256	            let _ = AttachConsole(ATTACH_PARENT_PROCESS);
257	        }
258	    }
259	
260	    // `zed --printenv` Outputs environment variables as JSON to stdout
261	    if args.printenv {
262	        util::shell_env::print_env();
263	        return;
264	    }
265	
266	    if args.dump_all_actions {
267	        dump_all_gpui_actions();
268	        return;
269	    }
270	
271	    // Set custom data directory.
272	    if let Some(dir) = &args.user_data_dir {
273	        paths::set_custom_data_dir(dir);
274	    }
275	
276	    #[cfg(target_os = "windows")]
277	    match util::get_zed_cli_path() {
278	        Ok(path) => askpass::set_askpass_program(path),
279	        Err(err) => {
280	            eprintln!("Error: {}", err);
281	            if std::option_env!("ZED_BUNDLE").is_some() {
282	                process::exit(1);
283	            }
284	        }
285	    }
286	
287	    let file_errors = init_paths();
288	    if !file_errors.is_empty() {
289	        files_not_created_on_launch(file_errors);
290	        return;
291	    }
292	
293	    zlog::init();
294	
295	    if stdout_is_a_pty() {
296	        zlog::init_output_stdout();
297	    } else {
298	        let result = zlog::init_output_file(paths::log_file(), Some(paths::old_log_file()));
299	        if let Err(err) = result {
300	            eprintln!("Could not open log file: {}... Defaulting to stdout", err);
301	            zlog::init_output_stdout();
302	        };
303	    }
304	    ztracing::init();
305	
306	    let version = option_env!("ZED_BUILD_ID");
307	    let app_commit_sha =
308	        option_env!("ZED_COMMIT_SHA").map(|commit_sha| AppCommitSha::new(commit_sha.to_string()));
309	    let app_version = AppVersion::load(env!("CARGO_PKG_VERSION"), version, app_commit_sha.clone());
310	
311	    if args.system_specs {
312	        let system_specs = system_specs::SystemSpecs::new_stateless(
313	            app_version,
314	            app_commit_sha,
315	            *release_channel::RELEASE_CHANNEL,
316	            client::telemetry::os_name(),
317	            client::telemetry::os_version(),
318	        );
319	        println!("Zed System Specs (from CLI):\n{}", system_specs);
320	        return;
321	    }
322	
323	    rayon::ThreadPoolBuilder::new()
324	        .num_threads(std::thread::available_parallelism().map_or(1, |n| n.get().div_ceil(2)))
325	        .stack_size(10 * 1024 * 1024)
326	        .thread_name(|ix| format!("RayonWorker{}", ix))
327	        .build_global()
328	        .unwrap();
329	
330	    log::info!(
331	        "========== starting zed version {}, sha {} ==========",
332	        app_version,
333	        app_commit_sha
334	            .as_ref()
335	            .map(|sha| sha.short())
336	            .as_deref()
337	            .unwrap_or("unknown"),
338	    );
339	
340	    #[cfg(windows)]
341	    check_for_conpty_dll();
342	
343	    let app = build_application().with_assets(Assets);
344	
345	    let app_db = db::AppDatabase::new();
346	    let system_id = app.background_executor().spawn(system_id());
347	    let installation_id = app
348	        .background_executor()
349	        .spawn(installation_id(KeyValueStore::from_app_db(&app_db)));
350	    let session_id = Uuid::new_v4().to_string();
351	    let session = app.background_executor().spawn(Session::new(
352	        session_id.clone(),
353	        KeyValueStore::from_app_db(&app_db),
354	    ));
355	    let background_executor = app.background_executor();
356	
357	    let (open_listener, mut open_rx) = OpenListener::new();
358	
359	    let failed_single_instance_check = if *zed_env_vars::ZED_STATELESS
360	        || *release_channel::RELEASE_CHANNEL == ReleaseChannel::Dev
361	    {
362	        false
363	    } else {
364	        #[cfg(any(target_os = "linux", target_os = "freebsd"))]
365	        {
366	            crate::zed::listen_for_cli_connections(open_listener.clone()).is_err()
367	        }
368	
369	        #[cfg(target_os = "windows")]
370	        {
371	            !crate::zed::windows_only_instance::handle_single_instance(open_listener.clone(), &args)
372	        }
373	
374	        #[cfg(target_os = "macos")]
375	        {
376	            use zed::mac_only_instance::*;
377	            ensure_only_instance() != IsOnlyInstance::Yes
