818	fn setup_or_teardown_ai_panel<P: Panel>(
819	    workspace: &mut Workspace,
820	    window: &mut Window,
821	    cx: &mut Context<Workspace>,
822	    load_panel: impl FnOnce(
823	        WeakEntity<Workspace>,
824	        AsyncWindowContext,
825	    ) -> Task<anyhow::Result<Entity<P>>>
826	    + 'static,
827	) -> Task<anyhow::Result<()>> {
828	    let disable_ai = SettingsStore::global(cx)
829	        .get::<DisableAiSettings>(None)
830	        .disable_ai
831	        || cfg!(test);
832	    let existing_panel = workspace.panel::<P>(cx);
833	    match (disable_ai, existing_panel) {
834	        (false, None) => cx.spawn_in(window, async move |workspace, cx| {
835	            let panel = load_panel(workspace.clone(), cx.clone()).await?;
836	            workspace.update_in(cx, |workspace, window, cx| {
837	                let disable_ai = SettingsStore::global(cx)
838	                    .get::<DisableAiSettings>(None)
839	                    .disable_ai;
840	                let have_panel = workspace.panel::<P>(cx).is_some();
841	                if !disable_ai && !have_panel {
842	                    workspace.add_panel(panel, window, cx);
843	                }
844	            })
845	        }),
846	        (true, Some(existing_panel)) => {
847	            workspace.remove_panel::<P>(&existing_panel, window, cx);
848	            Task::ready(Ok(()))
849	        }
850	        _ => Task::ready(Ok(())),
851	    }
852	}
