243	    fn parse_git_clone_url(&mut self, clone_path: &str) -> Result<()> {
244	        // Format: /?repo=<url> or ?repo=<url>
245	        let clone_path = clone_path.strip_prefix('/').unwrap_or(clone_path);
246	
247	        let query = clone_path
248	            .strip_prefix('?')
249	            .context("invalid git clone url: missing query string")?;
250	
251	        let repo_url = url::form_urlencoded::parse(query.as_bytes())
252	            .find_map(|(key, value)| (key == "repo").then_some(value))
253	            .filter(|s| !s.is_empty())
254	            .context("invalid git clone url: missing repo query parameter")?
255	            .to_string()
256	            .into();
257	
258	        self.kind = Some(OpenRequestKind::GitClone { repo_url });
259	
260	        Ok(())
261	    }
