263	    fn parse_git_commit_url(&mut self, commit_path: &str) -> Result<()> {
264	        // Format: <sha>?repo=<path>
265	        let (sha, query) = commit_path
266	            .split_once('?')
267	            .context("invalid git commit url: missing query string")?;
268	        anyhow::ensure!(!sha.is_empty(), "invalid git commit url: missing sha");
269	
270	        let repo = url::form_urlencoded::parse(query.as_bytes())
271	            .find_map(|(key, value)| (key == "repo").then_some(value))
272	            .filter(|s| !s.is_empty())
273	            .context("invalid git commit url: missing repo query parameter")?
274	            .to_string();
275	
276	        self.open_paths.push(repo);
277	
278	        self.kind = Some(OpenRequestKind::GitCommit {
279	            sha: sha.to_string(),
280	        });
281	
282	        Ok(())
283	    }
