285	    fn parse_ssh_file_path(&mut self, file: &str, cx: &App) -> Result<()> {
286	        let url = parse_ssh_url(file)?;
287	        let host = match url
288	            .host()
289	            .with_context(|| format!("missing host in ssh url: {url}"))?
290	        {
291	            url::Host::Domain(host) => host.to_string(),
292	            url::Host::Ipv4(host) => host.to_string(),
293	            url::Host::Ipv6(host) => host.to_string(),
294	        };
295	        let username = if url.username().is_empty() {
296	            None
297	        } else {
298	            Some(urlencoding::decode(url.username())?.into_owned())
299	        };
300	        let port = url.port();
301	        anyhow::ensure!(
302	            self.open_paths.is_empty(),
303	            "cannot open both local and ssh paths"
304	        );
305	        let mut connection_options =
306	            RemoteSettings::get_global(cx).connection_options_for(host, port, username);
307	        if let Some(password) = url.password() {
308	            connection_options.password = Some(urlencoding::decode(password)?.into_owned());
309	        }
310	
311	        let connection_options = RemoteConnectionOptions::Ssh(connection_options);
312	        if let Some(ssh_connection) = &self.remote_connection {
313	            anyhow::ensure!(
314	                *ssh_connection == connection_options,
315	                "cannot open multiple different remote connections"
316	            );
317	        }
318	        self.remote_connection = Some(connection_options);
319	        self.parse_file_path(url.path());
320	        Ok(())
321	    }
