324	fn parse_ssh_url(url: &str) -> Result<url::Url> {
325	    if let Ok(url) = url::Url::parse(url) {
326	        return Ok(url);
327	    }
328	    // SCP/git style urls use ':' to separate from Authority and Path.
329	    // They are unsupported by Url::parse, but can be normalized into a Url.
330	    //   SCPUrl("ssh://user@host:~/relpath") => Url("ssh://user@host/~/relpath")
331	    //   SCPUrl("ssh://user@host:/abs/path") => Url("ssh://user@host/abs/path")
332	    //
333	    // TODO: Add IPv6 support: "ssh://[2600::]:~/foo"
334	    let ssh_target = url
335	        .strip_prefix("ssh://")
336	        .with_context(|| format!("invalid ssh url: {url}"))?;
337	
338	    let (authority, path) = if let Some((authority, path)) = ssh_target.rsplit_once(":~/") {
339	        (authority, format!("/~/{path}"))
340	    } else if let Some((authority, path)) = ssh_target.rsplit_once(":/") {
341	        (authority, format!("/{path}"))
342	    } else {
343	        anyhow::bail!("invalid ssh url: {url}");
344	    };
345	
346	    let (userinfo, host) = authority
347	        .rsplit_once('@')
348	        .map_or((None, authority), |(userinfo, host)| (Some(userinfo), host));
349	    anyhow::ensure!(
350	        !host.is_empty() && !host.starts_with('[') && !host.contains(':'),
351	        "invalid ssh url: {url}"
352	    );
353	
354	    let normalized_authority = if let Some(userinfo) = userinfo {
355	        let (username, colon_password) =
356	            if let Some((username, password)) = userinfo.split_once(':') {
357	                (
358	                    urlencoding::encode(&urlencoding::decode(username)?).into_owned(),
359	                    format!(
360	                        ":{}",
361	                        urlencoding::encode(&urlencoding::decode(password)?).into_owned()
362	                    ),
363	                )
364	            } else {
365	                (
366	                    urlencoding::encode(&urlencoding::decode(userinfo)?).into_owned(),
367	                    String::new(),
368	                )
369	            };
370	        format!("{username}{colon_password}@{host}")
371	    } else {
372	        authority.to_string()
373	    };
374	
375	    Ok(url::Url::parse(&format!(
376	        "ssh://{normalized_authority}{path}"
377	    ))?)
378	}
