409	#[cfg(any(target_os = "linux", target_os = "freebsd"))]
410	pub fn listen_for_cli_connections(opener: OpenListener) -> Result<()> {
411	    use release_channel::RELEASE_CHANNEL_NAME;
412	    use std::os::unix::net::UnixDatagram;
413	
414	    let sock_path = paths::data_dir().join(format!("zed-{}.sock", *RELEASE_CHANNEL_NAME));
415	    // remove the socket if the process listening on it has died
416	    if let Err(e) = UnixDatagram::unbound()?.connect(&sock_path)
417	        && e.kind() == std::io::ErrorKind::ConnectionRefused
418	    {
419	        std::fs::remove_file(&sock_path)?;
420	    }
421	    let listener = UnixDatagram::bind(&sock_path)?;
422	    thread::spawn(move || {
423	        let mut buf = [0u8; 1024];
424	        while let Ok(len) = listener.recv(&mut buf) {
425	            opener.open(RawOpenRequest {
426	                urls: vec![String::from_utf8_lossy(&buf[..len]).to_string()],
427	                ..Default::default()
428	            });
429	        }
430	    });
431	    Ok(())
432	}
