434	fn connect_to_cli(
435	    server_name: &str,
436	) -> Result<(
437	    mpsc::UnboundedReceiver<CliRequest>,
438	    Box<dyn CliResponseSink>,
439	)> {
440	    let handshake_tx = ipc::IpcSender::<IpcHandshake>::connect(server_name.to_string())
441	        .context("error connecting to cli")?;
442	    let (request_tx, request_rx) = ipc::channel::<CliRequest>()?;
443	    let (response_tx, response_rx) = ipc::channel::<CliResponse>()?;
444	
445	    handshake_tx
446	        .send(IpcHandshake {
447	            requests: request_tx,
448	            responses: response_rx,
449	        })
450	        .context("error sending ipc handshake")?;
451	
452	    let (async_request_tx, async_request_rx) = futures::channel::mpsc::unbounded::<CliRequest>();
453	    thread::spawn(move || {
454	        while let Ok(cli_request) = request_rx.recv() {
455	            if async_request_tx.unbounded_send(cli_request).is_err() {
456	                break;
457	            }
458	        }
459	        anyhow::Ok(())
460	    });
461	
462	    Ok((async_request_rx, Box::new(response_tx)))
463	}
