465	pub async fn open_paths_with_positions(
466	    path_positions: &[PathWithPosition],
467	    diff_paths: &[[String; 2]],
468	    diff_all: bool,
469	    app_state: Arc<AppState>,
470	    open_options: workspace::OpenOptions,
471	    cx: &mut AsyncApp,
472	) -> Result<(
473	    WindowHandle<MultiWorkspace>,
474	    Vec<Option<Result<Box<dyn ItemHandle>>>>,
475	)> {
476	    let paths = path_positions
477	        .iter()
478	        .map(|path_with_position| path_with_position.path.clone())
479	        .collect::<Vec<_>>();
480	
481	    let OpenResult {
482	        window: multi_workspace,
483	        opened_items: mut items,
484	        ..
485	    } = cx
486	        .update(|cx| workspace::open_paths(&paths, app_state.clone(), open_options, cx))
487	        .await?;
488	
489	    if diff_all && !diff_paths.is_empty() {
490	        let mut diff_pairs = Vec::with_capacity(diff_paths.len());
491	        for diff_pair in diff_paths {
492	            let parsed = derive_paths_with_position(app_state.fs.as_ref(), diff_pair).await;
493	            let (Some(old_parsed), Some(new_parsed)) = (parsed.first(), parsed.get(1)) else {
494	                continue;
495	            };
496	            diff_pairs.push([
497	                old_parsed.path.to_string_lossy().into_owned(),
498	                new_parsed.path.to_string_lossy().into_owned(),
499	            ]);
500	        }
501	        if let Ok(diff_view) = multi_workspace.update(cx, |multi_workspace, window, cx| {
502	            multi_workspace.workspace().update(cx, |workspace, cx| {
503	                MultiDiffView::open(diff_pairs, workspace, window, cx)
504	            })
505	        }) {
506	            if let Some(diff_view) = diff_view.await.log_err() {
507	                items.push(Some(Ok(Box::new(diff_view))));
508	            }
509	        }
510	    } else {
511	        let workspace_weak = multi_workspace.read_with(cx, |multi_workspace, _cx| {
512	            multi_workspace.workspace().downgrade()
513	        })?;
514	        let canonicalize = async |parsed: &PathWithPosition| {
515	            app_state
516	                .fs
517	                .canonicalize(&parsed.path)
518	                .await
519	                .with_context(|| format!("opening --diff path {:?}", parsed.path))
520	        };
521	        for diff_pair in diff_paths {
522	            let parsed = derive_paths_with_position(app_state.fs.as_ref(), diff_pair).await;
523	            let (Some(old_parsed), Some(new_parsed)) = (parsed.first(), parsed.get(1)) else {
524	                continue;
525	            };
526	            let (old_path, new_path) =
527	                match futures::join!(canonicalize(old_parsed), canonicalize(new_parsed)) {
528	                    (Ok(old), Ok(new)) => (old, new),
529	                    (old, new) => {
530	                        for result in [old, new] {
531	                            if let Err(err) = result {
532	                                items.push(Some(Err(err)));
533	                            }
534	                        }
535	                        continue;
536	                    }
537	                };
538	            let target_position = new_parsed.row.map(|row| {
539	                language::Point::new(
540	                    row.saturating_sub(1),
541	                    new_parsed.column.unwrap_or(0).saturating_sub(1),
542	                )
543	            });
544	            if let Ok(diff_view) = multi_workspace.update(cx, |_multi_workspace, window, cx| {
545	                FileDiffView::open(
546	                    old_path,
547	                    new_path,
548	                    target_position,
549	                    workspace_weak.clone(),
550	                    window,
551	                    cx,
552	                )
553	            }) {
554	                if let Some(diff_view) = diff_view.await.log_err() {
555	                    items.push(Some(Ok(Box::new(diff_view))))
556	                }
557	            }
558	        }
559	    }
560	
561	    for (item, path) in items.iter_mut().zip(&paths) {
562	        if let Some(Err(error)) = item {
563	            *error = anyhow!("error opening {path:?}: {error:#}");
564	        }
565	    }
566	
567	    let items_for_navigation = items
568	        .iter()
569	        .map(|item| item.as_ref().and_then(|r| r.as_ref().ok()).cloned())
570	        .collect::<Vec<_>>();
571	    navigate_to_positions(&multi_workspace, items_for_navigation, path_positions, cx);
572	
573	    Ok((multi_workspace, items))
574	}
