576	pub async fn handle_cli_connection(
577	    (mut requests, responses): (
578	        mpsc::UnboundedReceiver<CliRequest>,
579	        Box<dyn CliResponseSink>,
580	    ),
581	    app_state: Arc<AppState>,
582	    cx: &mut AsyncApp,
583	) {
584	    if let Some(request) = requests.next().await {
585	        match request {
586	            CliRequest::Open {
587	                urls,
588	                paths,
589	                diff_paths,
590	                diff_all,
591	                wait,
592	                wsl,
593	                mut open_behavior,
594	                env,
595	                user_data_dir: _,
596	                dev_container,
597	                cwd,
598	            } => {
599	                if !urls.is_empty() {
600	                    cx.update(|cx| {
601	                        match OpenRequest::parse(
602	                            RawOpenRequest {
603	                                urls,
604	                                diff_paths,
605	                                diff_all,
606	                                dev_container,
607	                                wsl,
608	                                open_behavior: Some(open_behavior),
609	                            },
610	                            cx,
611	                        ) {
612	                            Ok(open_request) => {
613	                                cx.activate(true);
614	                                handle_open_request(open_request, app_state.clone(), cx);
615	                                responses.send(CliResponse::Exit { status: 0 }).log_err();
616	                            }
617	                            Err(e) => {
618	                                responses
619	                                    .send(CliResponse::Stderr {
620	                                        message: format!("{e}"),
621	                                    })
622	                                    .log_err();
623	                                responses.send(CliResponse::Exit { status: 1 }).log_err();
624	                            }
625	                        };
626	                    });
627	                    return;
628	                }
629	
630	                if open_behavior == cli::OpenBehavior::Default {
631	                    match resolve_open_behavior(
632	                        &paths,
633	                        &app_state,
634	                        responses.as_ref(),
635	                        &mut requests,
636	                        cx,
637	                    )
638	                    .await
639	                    {
640	                        Some(settings::CliDefaultOpenBehavior::ExistingWindow) => {
641	                            open_behavior = cli::OpenBehavior::ExistingWindow;
642	                        }
643	                        Some(settings::CliDefaultOpenBehavior::NewWindow) => {
644	                            open_behavior = cli::OpenBehavior::PreferNewWindow;
645	                        }
646	                        None => {}
647	                    }
648	                }
649	
650	                if open_behavior == cli::OpenBehavior::Default {
651	                    open_behavior = cx.update(|cx| open_behavior_for_default_setting(cx));
652	                }
653	
654	                cx.update(|cx| cx.activate(true));
655	
656	                let open_workspace_result = open_workspaces(
657	                    paths,
658	                    diff_paths,
659	                    diff_all,
660	                    open_behavior,
661	                    responses.as_ref(),
662	                    wait,
663	                    dev_container,
664	                    app_state.clone(),
665	                    env,
666	                    cwd,
667	                    cx,
668	                )
669	                .await;
670	
671	                let status = if open_workspace_result.is_err() { 1 } else { 0 };
672	                responses.send(CliResponse::Exit { status }).log_err();
673	            }
674	            CliRequest::SetOpenBehavior { .. } => {
675	                // We handle this case in a situation-specific way in
676	                // resolve_open_behavior
677	                debug_panic!("unexpected SetOpenBehavior message");
678	            }
679	        }
680	    }
681	}
