683	/// Resolves the CLI open behavior when no explicit open behavior flag was given.
684	/// May prompt the user interactively on first run.
685	///
686	/// Returns `Some(behavior)` to override the default, or `None` if no override
687	/// is needed (e.g. no existing windows, paths already in a workspace, or the
688	/// user has already configured `cli_default_open_behavior` in settings).
689	async fn resolve_open_behavior(
690	    paths: &[String],
691	    app_state: &Arc<AppState>,
692	    responses: &dyn CliResponseSink,
693	    requests: &mut mpsc::UnboundedReceiver<CliRequest>,
694	    cx: &mut AsyncApp,
695	) -> Option<settings::CliDefaultOpenBehavior> {
696	    let has_existing_windows = cx.update(|cx| {
697	        cx.windows()
698	            .iter()
699	            .any(|window| window.downcast::<MultiWorkspace>().is_some())
700	    });
701	
702	    if !has_existing_windows {
703	        return None;
704	    }
705	
706	    if !paths.is_empty() {
707	        let paths_as_pathbufs: Vec<PathBuf> = paths.iter().map(PathBuf::from).collect();
708	        let paths_in_existing_workspace = cx.update(|cx| {
709	            for window in cx.windows() {
710	                if let Some(multi_workspace) = window.downcast::<MultiWorkspace>() {
711	                    if let Ok(multi_workspace) = multi_workspace.read(cx) {
712	                        for workspace in multi_workspace.workspaces() {
713	                            let project = workspace.read(cx).project().read(cx);
714	                            if project
715	                                .visibility_for_paths(&paths_as_pathbufs, false, cx)
716	                                .is_some()
717	                            {
718	                                return true;
719	                            }
720	                        }
721	                    }
722	                }
723	            }
724	            false
725	        });
726	
727	        if paths_in_existing_workspace {
728	            return None;
729	        }
730	    }
731	
732	    if !paths.is_empty() {
733	        let has_directory =
734	            futures::future::join_all(paths.iter().map(|p| app_state.fs.is_dir(Path::new(p))))
735	                .await
736	                .into_iter()
737	                .any(|is_dir| is_dir);
738	
739	        if !has_directory {
740	            return None;
741	        }
742	    }
743	
744	    let settings_text = app_state
745	        .fs
746	        .load(paths::settings_file())
747	        .await
748	        .unwrap_or_default();
749	
750	    if settings_text.contains("cli_default_open_behavior") {
751	        return None;
752	    }
753	
754	    responses.send(CliResponse::PromptOpenBehavior).log_err()?;
755	
756	    if let Some(CliRequest::SetOpenBehavior { behavior }) = requests.next().await {
757	        let behavior = match behavior {
758	            cli::CliBehaviorSetting::ExistingWindow => {
759	                settings::CliDefaultOpenBehavior::ExistingWindow
760	            }
761	            cli::CliBehaviorSetting::NewWindow => settings::CliDefaultOpenBehavior::NewWindow,
762	        };
763	
764	        let fs = app_state.fs.clone();
765	        cx.update(|cx| {
766	            settings::update_settings_file(fs, cx, move |content, _cx| {
767	                content.workspace.cli_default_open_behavior = Some(behavior);
768	            });
769	        });
770	
771	        return Some(behavior);
772	    }
773	
774	    None
775	}
