783	        match workspace::WorkspaceSettings::get_global(cx).default_open_behavior {
784	            settings::DefaultOpenBehavior::ExistingWindow => cli::OpenBehavior::ExistingWindow,
785	            settings::DefaultOpenBehavior::NewWindow => cli::OpenBehavior::PreferNewWindow,
