791	pub(crate) fn open_options_for_behavior(
792	    open_behavior: cli::OpenBehavior,
793	    location: &SerializedWorkspaceLocation,
794	    cx: &App,
795	) -> workspace::OpenOptions {
796	    let open_behavior = if open_behavior == cli::OpenBehavior::Default {
797	        open_behavior_for_default_setting(cx)
798	    } else {
799	        open_behavior
800	    };
801	
802	    // If reuse flag is passed, open a new workspace in an existing window.
803	    let requesting_window = if open_behavior == cli::OpenBehavior::Reuse {
804	        workspace::workspace_windows_for_location(location, cx)
805	            .into_iter()
806	            .next()
807	    } else {
808	        None
809	    };
810	    workspace::OpenOptions {
811	        workspace_matching: match open_behavior {
812	            cli::OpenBehavior::AlwaysNew | cli::OpenBehavior::Reuse => {
813	                workspace::WorkspaceMatching::None
814	            }
815	            cli::OpenBehavior::PreferNewWindow => workspace::WorkspaceMatching::MatchSubpaths,
816	            cli::OpenBehavior::Add => workspace::WorkspaceMatching::MatchSubdirectory,
817	            _ => workspace::WorkspaceMatching::MatchExact,
818	        },
819	        add_dirs_to_sidebar: match open_behavior {
820	            cli::OpenBehavior::ExistingWindow => true,
821	            _ => false,
822	        },
823	        requesting_window,
824	        ..Default::default()
825	    }
826	}
