835	async fn open_workspaces(
836	    paths: Vec<String>,
837	    diff_paths: Vec<[String; 2]>,
838	    diff_all: bool,
839	    open_behavior: cli::OpenBehavior,
840	    responses: &dyn CliResponseSink,
841	    wait: bool,
842	    dev_container: bool,
843	    app_state: Arc<AppState>,
844	    env: Option<collections::HashMap<String, String>>,
845	    cwd: Option<PathBuf>,
846	    cx: &mut AsyncApp,
847	) -> Result<()> {
848	    if paths.is_empty()
849	        && diff_paths.is_empty()
850	        && !matches!(open_behavior, cli::OpenBehavior::AlwaysNew)
851	    {
852	        return restore_or_create_workspace(app_state, cx).await;
853	    }
854	
855	    let grouped_locations: Vec<(SerializedWorkspaceLocation, PathList)> =
856	        if paths.is_empty() && diff_paths.is_empty() {
857	            Vec::new()
858	        } else {
859	            vec![(
860	                SerializedWorkspaceLocation::Local,
861	                PathList::new(&paths.into_iter().map(PathBuf::from).collect::<Vec<_>>()),
862	            )]
863	        };
864	
865	    if grouped_locations.is_empty() {
866	        // If we have no paths to open, show the welcome screen if this is the first launch
867	        let kvp = cx.update(|cx| KeyValueStore::global(cx));
868	        if matches!(kvp.read_kvp(FIRST_OPEN), Ok(None)) {
869	            cx.update(|cx| show_onboarding_view(app_state, cx).detach());
870	        }
871	        // If not the first launch, show an empty window with empty editor
872	        else {
873	            cx.update(|cx| {
874	                let open_options = OpenOptions {
875	                    env,
876	                    ..Default::default()
877	                };
878	                workspace::open_new(open_options, app_state, cx, |workspace, window, cx| {
879	                    Editor::new_file(workspace, &Default::default(), window, cx)
880	                })
881	                .detach_and_log_err(cx);
882	            });
883	        }
884	        return Ok(());
885	    }
886	    // If there are paths to open, open a workspace for each grouping of paths
887	    let mut errored = false;
888	
889	    for (location, workspace_paths) in grouped_locations {
890	        let base_open_options =
891	            cx.update(|cx| open_options_for_behavior(open_behavior, &location, cx));
892	        let open_options = workspace::OpenOptions {
893	            wait,
894	            env: env.clone(),
895	            open_in_dev_container: dev_container,
896	            ..base_open_options
897	        };
898	
899	        match location {
900	            SerializedWorkspaceLocation::Local => {
901	                let workspace_paths = workspace_paths
902	                    .paths()
903	                    .iter()
904	                    .map(|path| path.to_string_lossy().into_owned())
905	                    .collect();
906	
907	                let workspace_failed_to_open = open_local_workspace(
908	                    workspace_paths,
909	                    diff_paths.clone(),
910	                    diff_all,
911	                    open_options,
912	                    cwd.clone(),
913	                    responses,
914	                    &app_state,
915	                    cx,
916	                )
917	                .await;
918	
919	                if workspace_failed_to_open {
920	                    errored = true
921	                }
922	            }
923	            SerializedWorkspaceLocation::Remote(mut connection) => {
924	                let app_state = app_state.clone();
925	                if let RemoteConnectionOptions::Ssh(options) = &mut connection {
926	                    cx.update(|cx| {
927	                        RemoteSettings::get_global(cx)
928	                            .fill_connection_options_from_settings(options)
929	                    });
930	                }
931	                cx.spawn(async move |cx| {
932	                    open_remote_project(
933	                        connection,
934	                        workspace_paths.paths().to_vec(),
935	                        app_state,
936	                        open_options,
937	                        cx,
938	                    )
939	                    .await
940	                    .log_err();
941	                })
942	                .detach();
943	            }
944	        }
945	    }
946	
947	    anyhow::ensure!(!errored, "failed to open a workspace");
948	
949	    Ok(())
950	}
