952	async fn open_local_workspace(
953	    mut workspace_paths: Vec<String>,
954	    diff_paths: Vec<[String; 2]>,
955	    diff_all: bool,
956	    open_options: workspace::OpenOptions,
957	    cwd: Option<PathBuf>,
958	    responses: &dyn CliResponseSink,
959	    app_state: &Arc<AppState>,
960	    cx: &mut AsyncApp,
961	) -> bool {
962	    let user_provided_paths = !workspace_paths.is_empty();
963	
964	    // When only diff paths are provided (no regular paths), add the CLI's
965	    // working directory so the workspace opens with the right context.
966	    // Note: must use the CLI process's cwd (forwarded via `cli_cwd`), not
967	    // `std::env::current_dir()`, since the Zed app process's cwd is typically
968	    // `/` on macOS bundles or the launch dir of an already-running instance.
969	    if !user_provided_paths
970	        && !diff_paths.is_empty()
971	        && let Some(cwd) = cwd
972	    {
973	        workspace_paths.push(cwd.to_string_lossy().to_string());
974	    }
975	
976	    let paths_with_position =
977	        derive_paths_with_position(app_state.fs.as_ref(), workspace_paths).await;
978	
979	    let (workspace, items) = match open_paths_with_positions(
980	        &paths_with_position,
981	        &diff_paths,
982	        diff_all,
983	        app_state.clone(),
984	        open_options.clone(),
985	        cx,
986	    )
987	    .await
988	    {
989	        Ok(result) => result,
990	        Err(error) => {
991	            let paths = paths_with_position
992	                .iter()
993	                .map(|p| p.path.display().to_string())
994	                .collect::<Vec<_>>()
995	                .join(", ");
996	            log::error!("failed to open workspace [{paths}]: {error:#}");
997	            responses
998	                .send(CliResponse::Stderr {
999	                    message: format!("error opening [{paths}]: {error:#}"),
1000	                })
1001	                .log_err();
1002	            return true;
1003	        }
1004	    };
1005	
1006	    let mut errored = false;
1007	    let mut item_release_futures = Vec::new();
1008	    let mut subscriptions = Vec::new();
1009	    // If --wait flag is used with no paths, or a directory, then wait until
1010	    // the entire workspace is closed.
1011	    if open_options.wait {
1012	        let mut wait_for_window_close = paths_with_position.is_empty() && diff_paths.is_empty();
1013	        if user_provided_paths {
1014	            for path_with_position in &paths_with_position {
1015	                if app_state.fs.is_dir(&path_with_position.path).await {
1016	                    wait_for_window_close = true;
1017	                    break;
1018	                }
1019	            }
1020	        }
1021	
1022	        if wait_for_window_close {
1023	            let (release_tx, release_rx) = oneshot::channel();
1024	            item_release_futures.push(release_rx);
1025	            subscriptions.push(workspace.update(cx, |_, _, cx| {
1026	                cx.on_release(move |_, _| {
1027	                    let _ = release_tx.send(());
1028	                })
1029	            }));
1030	        }
1031	    }
1032	
1033	    for item in items {
1034	        match item {
1035	            Some(Ok(item)) => {
1036	                if open_options.wait {
1037	                    let (release_tx, release_rx) = oneshot::channel();
1038	                    item_release_futures.push(release_rx);
1039	                    subscriptions.push(Ok(cx.update(|cx| {
1040	                        item.on_release(
1041	                            cx,
1042	                            Box::new(move |_| {
1043	                                release_tx.send(()).ok();
1044	                            }),
1045	                        )
1046	                    })));
1047	                }
1048	            }
1049	            Some(Err(err)) => {
1050	                log::error!("{err:#}");
1051	                responses
1052	                    .send(CliResponse::Stderr {
1053	                        message: format!("{err:#}"),
1054	                    })
1055	                    .log_err();
1056	                errored = true;
1057	            }
1058	            None => {}
1059	        }
1060	    }
1061	
1062	    if open_options.wait {
1063	        let wait = async move {
1064	            let _subscriptions = subscriptions;
1065	            let _ = future::try_join_all(item_release_futures).await;
1066	        }
1067	        .fuse();
1068	        futures::pin_mut!(wait);
1069	
1070	        let background = cx.background_executor().clone();
1071	        loop {
1072	            // Repeatedly check if CLI is still open to avoid wasting resources
1073	            // waiting for files or workspaces to close.
1074	            let mut timer = background.timer(Duration::from_secs(1)).fuse();
1075	            futures::select_biased! {
1076	                _ = wait => break,
1077	                _ = timer => {
1078	                    if responses.send(CliResponse::Ping).is_err() {
1079	                        break;
1080	                    }
1081	                }
1082	            }
1083	        }
1084	    }
1085	
1086	    errored
1087	}
