1089	pub async fn derive_paths_with_position(
1090	    fs: &dyn Fs,
1091	    path_strings: impl IntoIterator<Item = impl AsRef<str>>,
1092	) -> Vec<PathWithPosition> {
1093	    let path_strings: Vec<_> = path_strings.into_iter().collect();
1094	    let mut result = Vec::with_capacity(path_strings.len());
1095	    for path_str in path_strings {
1096	        let original_path = Path::new(path_str.as_ref());
1097	        let mut parsed = PathWithPosition::parse_str(path_str.as_ref());
1098	
1099	        // If the unparsed path string actually points to an existing file or directory, use it
1100	        // instead of parsing out the line/col number. This matters for paths whose final
1101	        // component looks like a position suffix, e.g. a folder named `Test (3)` would
1102	        // otherwise be parsed as `Test ` at row 3.
1103	        // Colon : is not valid in NTFS file names, so skip this logic if colon on windows.
1104	        let has_colon = original_path
1105	            .file_name()
1106	            .and_then(|name| name.to_str())
1107	            .is_none_or(|name| name.contains(':'));
1108	
1109	        if (!has_colon || !cfg!(windows))
1110	            && parsed.row.is_some()
1111	            && parsed.path != original_path
1112	            && (fs.is_file(original_path).await || fs.is_dir(original_path).await)
1113	        {
1114	            parsed = PathWithPosition::from_path(original_path.to_path_buf());
1115	        }
1116	
1117	        if let Ok(canonicalized) = fs.canonicalize(&parsed.path).await {
1118	            parsed.path = canonicalized;
1119	        }
1120	
1121	        result.push(parsed);
1122	    }
1123	    result
1124	}
