2446	    /// Runs the real [`cli::run_cli_response_loop`] on an OS thread against
2447	    /// the Zed-side `handle_cli_connection` on the GPUI foreground executor,
2448	    /// using `allow_parking` so the test scheduler tolerates cross-thread
2449	    /// wakeups.
2450	    ///
2451	    /// Returns `(exit_status, prompt_was_shown)`.
2452	    fn run_cli_with_zed_handler(
2453	        cx: &mut TestAppContext,
2454	        app_state: Arc<AppState>,
2455	        open_request: CliRequest,
2456	        prompt_response: Option<cli::CliBehaviorSetting>,
2457	    ) -> (i32, bool) {
2458	        cx.executor().allow_parking();
2459	
2460	        let (request_tx, request_rx) = mpsc::unbounded::<CliRequest>();
2461	        let (response_tx, response_rx) = std::sync::mpsc::channel::<CliResponse>();
2462	        let response_sink: Box<dyn CliResponseSink> = Box::new(SyncResponseSender(response_tx));
2463	
2464	        cx.spawn(|mut cx| async move {
2465	            handle_cli_connection((request_rx, response_sink), app_state, &mut cx).await;
2466	        })
2467	        .detach();
2468	
2469	        let prompt_called = Arc::new(std::sync::atomic::AtomicBool::new(false));
2470	        let prompt_called_for_thread = prompt_called.clone();
2471	
2472	        let cli_thread = std::thread::spawn(move || -> anyhow::Result<i32> {
2473	            request_tx
2474	                .unbounded_send(open_request)
2475	                .map_err(|error| anyhow::anyhow!("{error}"))?;
2476	
2477	            while let Ok(response) = response_rx.recv() {
2478	                match response {
2479	                    CliResponse::Ping => {}
2480	                    CliResponse::Stdout { .. } | CliResponse::Stderr { .. } => {}
2481	                    CliResponse::Exit { status } => return Ok(status),
2482	                    CliResponse::PromptOpenBehavior => {
2483	                        prompt_called_for_thread.store(true, std::sync::atomic::Ordering::SeqCst);
2484	                        let behavior =
2485	                            prompt_response.unwrap_or(cli::CliBehaviorSetting::ExistingWindow);
2486	                        request_tx
2487	                            .unbounded_send(CliRequest::SetOpenBehavior { behavior })
2488	                            .map_err(|error| anyhow::anyhow!("{error}"))?;
2489	                    }
2490	                }
2491	            }
2492	
2493	            anyhow::bail!("CLI response channel closed without Exit")
2494	        });
2495	
2496	        while !cli_thread.is_finished() {
2497	            cx.run_until_parked();
2498	            std::thread::sleep(std::time::Duration::from_millis(1));
2499	        }
2500	
2501	        let exit_status = cli_thread.join().unwrap().expect("CLI loop failed");
2502	        let prompt_shown = prompt_called.load(std::sync::atomic::Ordering::SeqCst);
2503	
2504	        // Flush any remaining async work (e.g. settings file writes).
2505	        cx.run_until_parked();
2506	
2507	        (exit_status, prompt_shown)
2508	    }
