            .update(cx, |_, window, _| window.remove_window())
            .unwrap();
        cx.run_until_parked();
        assert_eq!(cx.windows().len(), 0);

        cx.update(|cx| {
            app_state.session.update(cx, |app_session, _cx| {
                app_session.replace_session_for_test(Session::test_with_old_session(session_id));
            });
